/** True while this extension, not YouTube, has the Short moved aside. */
let slotTaken = false;

/**
 * Puts the panel where YouTube puts a Short's comments, by giving the Short
 * the attribute YouTube uses for them: on a wide window the Short moves left
 * and the panel sits beside it, clear of the up and down arrows; on a narrow
 * one YouTube floats the slot over the video. Opening YouTube's comments, or
 * clicking outside the floating panel, closes this one: never both at once.
 */
function placeInCommentsSlot(list: HTMLElement): void {
  const shorts = document.querySelector<HTMLElement>("ytd-shorts");
  const reel = player()?.closest("ytd-reel-video-renderer");
  const slot = document.getElementById("anchored-panel");
  if (!shorts || !reel || !slot) return;
  const theirs = document.querySelector(THEIR_PANEL);
  if (!theirs) closingTheirs = false;
  else if (!closingTheirs) {
    listOpen = false;
    return render();
  }
  // Scrolling to the next Short moves the attribute to its renderer.
  for (const other of document.querySelectorAll(
    `ytd-reel-video-renderer[${WATCH_WHILE}]`,
  ))
    if (other !== reel) other.removeAttribute(WATCH_WHILE);
  for (const target of [shorts, reel])
    if (!target.hasAttribute(WATCH_WHILE)) target.setAttribute(WATCH_WHILE, "");

  slotTaken = true;
  // The same size and place as YouTube's comments: widening the slot squeezes
  // the Short's own frame and stretches the video.
  const box = slot.getBoundingClientRect();
  const css = `left: ${Math.round(box.left)}px; top: ${Math.round(box.top)}px; width: ${Math.round(box.width)}px; height: ${Math.round(box.height)}px;`;
  if (list.style.cssText !== css) list.style.cssText = css;
}

/** Puts the Short back where it was, unless YouTube's own panel holds it. */
function releaseCommentsSlot(): void {
  if (!slotTaken) return;
  slotTaken = false;
  if (document.querySelector(THEIR_PANEL)) return;
  for (const target of document.querySelectorAll(`[${WATCH_WHILE}]`))
    target.removeAttribute(WATCH_WHILE);
}

/** True from asking YouTube's panel to close until it has. */
let closingTheirs = false;

/** Closes YouTube's comments (or description) so the claims panel has the slot. */
function closeTheirPanel(): void {
  const close = document.querySelector<HTMLElement>(
    `${THEIR_PANEL} #visibility-button button`,
  );
  if (!close) return;
  closingTheirs = true;
  close.click();
}

function renderList(): void {
  const existing = document.getElementById(LIST_ID);
  const shorts = onShorts();
  if (!enabled || !listOpen || currentVideoId() === null) {
    releaseCommentsSlot();
    return existing?.remove();
  }
  const list = existing ?? element("section");
  list.id = LIST_ID;
  list.setAttribute("aria-label", "Claims in this video");
  list.replaceChildren(listHeader(), ...listBody());
  list.toggleAttribute("data-shorts", shorts);
  if (shorts) {
    // A panel in the Short's comments slot, in place of its comments.
    if (!existing) closeTheirPanel();
    if (list.parentElement !== document.body) document.body.append(list);

